<?php declare(strict_types=1); ?>
<section class="module-toolbar"><div><p class="module-intro">Sipariş, ödeme, stok, izin ve sistem uyarılarınızı tek merkezden takip edin.</p><span class="result-count"><?= $unread ?> okunmamış bildirim</span></div><?php if($unread): ?><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="read_all"><button class="btn secondary">Tümünü okundu işaretle</button></form><?php endif; ?></section>
<section class="panel notification-list"><?php foreach($notifications as $n): ?><article class="notification-item <?= $n['read_at']===null?'unread':'' ?>"><div class="notification-dot <?= kd_e($n['type']) ?>"></div><div class="notification-body"><strong><?= kd_e($n['title']) ?></strong><p><?= kd_e($n['message']) ?></p><small><?= kd_e(date('d.m.Y H:i',strtotime($n['created_at']))) ?></small><?php if($n['url']): ?><a href="<?= kd_e($n['url']) ?>">İlgili kaydı aç →</a><?php endif; ?></div><?php if($n['read_at']===null): ?><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="read"><input type="hidden" name="notification_id" value="<?= (int)$n['id'] ?>"><button class="btn secondary">Okundu</button></form><?php endif; ?></article><?php endforeach; ?><?php if(!$notifications): ?><p class="empty-state">Henüz bildiriminiz yok.</p><?php endif; ?></section>
